import type React from 'react'
import {NinetailedProvider} from '@ninetailed/experience.js-react'
import type {Locale} from '@ninetailed/experience.js-shared'
import {NinetailedInsightsPlugin} from '@ninetailed/experience.js-plugin-insights'

import {NinetailedSetup} from './NinetailedSetup'

const ninetailedPlugins = [new NinetailedInsightsPlugin()]

interface NinetailedWrapperProps {
  clientId: string
  environment: string
  /** ISO 639-1 language code (e.g., 'en', 'es', 'fr') - already converted by App.tsx */
  locale: string
  children: React.ReactNode
}

export default function NinetailedWrapper({clientId, environment, locale, children}: NinetailedWrapperProps) {
  return (
    <NinetailedProvider
      clientId={clientId}
      environment={environment}
      locale={locale as Locale}
      plugins={ninetailedPlugins}
    >
      <NinetailedSetup>{children}</NinetailedSetup>
    </NinetailedProvider>
  )
}
