import {useEffect} from 'react'
import {useNinetailed} from '@ninetailed/experience.js-react'

import {NinetailedTrackProvider} from './NinetailedTrackContext'

/**
 * Sends a page view event on mount and exposes track() to all descendants
 * via NinetailedTrackProvider. Must be rendered inside NinetailedProvider.
 */
export function NinetailedSetup({children}: {children: React.ReactNode}) {
  const {page, track} = useNinetailed()

  useEffect(() => {
    page()
  }, [page])

  return <NinetailedTrackProvider track={track}>{children}</NinetailedTrackProvider>
}
